<script setup lang="ts">
import {ref} from 'vue'
import {useStudio} from './studioContext'
const props=defineProps<{page?:string}>(),s=useStudio(),plan=ref<any>(null),error=ref(''),requestId=ref(''),done=ref(false),working=ref(false)
const labels:Record<string,string>={publish:'确认草稿',acknowledge:'已核对，继续使用',identity:'确认人物对应'}
async function preview(){error.value='';done.value=false;working.value=true;try{const ok=await s.run(async()=>{await s.saveAll();const value=await s.api(`/projects/${s.p.value.id}/studio/batch-confirm/preview`,'POST',{version:s.p.value.version,scope:props.page?'page':'project',page:props.page||'library'});plan.value=value;requestId.value=crypto.randomUUID()});if(!ok)error.value=s.error.value}catch(e:any){error.value=e.message}finally{working.value=false}}
async function confirm(){working.value=true;error.value='';try{const ok=await s.run(async()=>{const p=plan.value;if(s.p.value.id!==p.projectId)throw Error('项目已切换，请重新打开批量清单');const result=await s.api(`/projects/${p.projectId}/studio/batch-confirm`,'POST',{version:p.version,scope:p.scope,page:p.page,keys:p.keys,previewHash:p.previewHash,requestId:requestId.value});await s.legacy(result.project);plan.value=result.result;done.value=true});if(!ok)error.value=s.error.value}catch(e:any){error.value=e.message}finally{working.value=false}}
</script>
<template><button :disabled="working||s.busy.value||!s.p.value" @click="preview">{{page?'一键确认本页':'全项目一键确认'}}</button><p v-if="error&&!plan" class="extension-error">{{error}}</p><Teleport to="body"><div v-if="plan" class="modal batch-modal" role="dialog" aria-modal="true" aria-label="批量确认清单"><article><h2>{{done?'批量确认已完成':'批量确认清单'}}</h2><p>共 {{plan.eligible.length}} 项{{done?'已处理':'可确认'}}，{{plan.skipped.length}} 项跳过。此操作不调用模型、不生成视频。</p><p class="muted">作品结构化资料随资料一并确认；不自动采用模型建议或解决一致性建议。</p><p v-if="error" class="extension-error" role="alert">{{error}}</p><ul><li v-for="item in plan.eligible" :key="item.key">{{item.name}} · {{labels[item.action]}}</li></ul><details v-if="plan.skipped.length" open><summary>跳过的内容及原因</summary><p v-for="item in plan.skipped" :key="item.key">{{item.name}}：{{item.reason}}</p></details><div class="actions"><button v-if="!done" class="primary" :disabled="working||!plan.eligible.length" @click="confirm">{{working?'正在确认…':'确认这 '+plan.eligible.length+' 项'}}</button><button :disabled="working" @click="plan=null">{{done?'关闭':'取消'}}</button></div></article></div></Teleport></template>
<style scoped>.batch-modal article{max-height:85vh;overflow:auto;max-width:760px;width:90vw}.batch-modal li{margin:8px 0}</style>
